export const seamanshipQuestionsExtended: QuizQuestion[] = [
  { id: 86, question: "Demirleme yerinde su derinliği 40 m ise iyi hava koşullarında verilecek kaloma yaklaşık ne kadar olmalıdır?", options: ["400 m", "80 m", "160 m", "240 m"], correctAnswer: 3, explanation: "İyi havada kaloma genellikle derinliğin 5–6 katıdır: 40 × 6 = 240 m (yaklaşık 9 kilit).", category: "Demirleme" },
  { id: 87, question: "Bir kilit (shackle) zincir kaç metredir?", options: ["15 m", "20.5 m", "27.5 m", "30 m"], correctAnswer: 2, explanation: "Bir kilit 15 kulaç, yani yaklaşık 27.5 m'dir; kaloma hesapları kilit cinsinden yapılır.", category: "Demirleme" },
  { id: 88, question: "Suya verilen 7 kilit zincir yaklaşık kaç metredir?", options: ["193 m", "220 m", "247 m", "165 m"], correctAnswer: 0, explanation: "7 × 27.5 = 192.5 ≈ 193 m.", category: "Demirleme" },
  { id: 89, question: "Demir tutmasında zincirin yatay çekiş sağlaması neden önemlidir?", options: ["Gürültü olmasın diye", "Zincir kısalsın diye", "Zincir aşınmasın diye", "Demirin tırnaklarının dibe gömülmesini sağladığı için"], correctAnswer: 3, explanation: "Yeterli kaloma zincirin dipte yatay uzanmasını sağlar; çekme açısı büyürse demir dipten sıyrılır (taramaya başlar).", category: "Demirleme" },
  { id: 90, question: "Demir taraması (dragging) nasıl anlaşılır?", options: ["Pruva rüzgâra döner", "Zincir gerginliği azalır", "Konum sabit kalır", "Zincirde düzensiz titreşim/sarsıntı olur ve GPS konumu sürüklenir"], correctAnswer: 3, explanation: "Zincirde ritmik sarsıntı, kerteriz değişimi ve konum kayması taramanın işaretidir; makine hazır edilip kaloma artırılır veya yer değiştirilir.", category: "Demirleme" },
  { id: 91, question: "Demirleme sahasında swinging circle (dönüş dairesi) neye göre hesaplanır?", options: ["Rüzgâr hızına", "Yalnızca gemi boyuna", "Verilen kaloma ile gemi boyunun toplamına", "Su derinliğine"], correctAnswer: 2, explanation: "Yarıçap = suya verilen zincir uzunluğu + gemi boyu; bu daire içinde başka gemi veya tehlike bulunmamalıdır.", category: "Demirleme" },
  { id: 92, question: "Gemi boyu 180 m ve suya verilen zincir 200 m ise dönüş dairesi yarıçapı kaç metredir?", options: ["560 m", "200 m", "290 m", "380 m"], correctAnswer: 3, explanation: "Yarıçap = 200 + 180 = 380 m; demir mevkiine göre bu yarıçap haritada çizilerek emniyet kontrol edilir.", category: "Demirleme" },
  { id: 93, question: "Demirde vardiya tutarken en temel kontrol nedir?", options: ["Yalnızca hava raporu", "Konumun ve kerterizlerin düzenli kontrolüyle taramanın izlenmesi", "Yalnızca ışıkların yakılması", "Yalnızca telsiz dinleme"], correctAnswer: 1, explanation: "Sabit nesnelere kerteriz, radar mesafesi ve GPS demir alarmı birlikte kullanılır; hava kötüleştiğinde makine hazır tutulur.", category: "Demirleme" },
  { id: 94, question: "İki demirle (open moor) demirlemenin temel amacı nedir?", options: ["Dönüş dairesini küçültmek ve tutma gücünü artırmak", "Daha hızlı demir almak", "Zincir aşınmasını azaltmak", "Zincir tasarrufu"], correctAnswer: 0, explanation: "İki demir savrulmayı sınırlar ve rüzgâr/akıntı değişiminde daha kararlı tutuş sağlar; ancak zincirlerin dolanma riski yönetilmelidir.", category: "Demirleme" },
  { id: 95, question: "Demir alırken 'anchor aweigh' bildirimi ne anlama gelir?", options: ["Demir loçada", "Zincir kilitlendi", "Demir dipte", "Demir dipten ayrıldı ve gemi serbest"], correctAnswer: 3, explanation: "Bu andan itibaren gemi demirde sayılmaz; ilgili fener/işaret değiştirilir ve manevra kuralları uygulanır.", category: "Demirleme" },
  { id: 96, question: "Palamar halatlarında 'spring' halatın işlevi nedir?", options: ["Halatı korumak", "Gemiyi rıhtıma çekmek", "Geminin ileri-geri hareketini kısıtlamak", "Gemiyi kaldırmak"], correctAnswer: 2, explanation: "Baş ve kıç spring halatlar boyuna hareketi engeller; head/stern line ve breast line ise gemiyi rıhtıma yanaşık tutar.", category: "Palamar" },
  { id: 97, question: "Palamar halatlarında 'breast line' ne sağlar?", options: ["Demir yerine geçer", "Römorkör bağlantısı sağlar", "Boyuna hareketi engeller", "Gemiyi rıhtıma dik olarak çekip yanaşık tutar"], correctAnswer: 3, explanation: "Breast line rıhtıma yaklaşık dik açıyla verilir ve gemiyi rıhtıma yakın tutar; boyuna hareketi kısıtlamaz.", category: "Palamar" },
  { id: 98, question: "Bağlama sırasında karışık malzemeli (tel ve sentetik) halat kullanmak neden sakıncalıdır?", options: ["Farklı esneme özellikleri nedeniyle yükün dengesiz dağılıp tek halatın kopmasına yol açması nedeniyle", "Ağırlık nedeniyle", "Maliyet nedeniyle", "Renk uyumsuzluğu nedeniyle"], correctAnswer: 0, explanation: "Az esneyen tel halat yükü önce üstlenir ve kopar; aynı görevdeki tüm halatlar aynı malzeme ve boyutta olmalıdır.", category: "Palamar" },
  { id: 99, question: "Snap-back bölgesi nedir?", options: ["Vinç kontrol alanı", "Demir sahası", "Halatın saklandığı yer", "Kopan halatın savrulacağı tahmini tehlike alanı"], correctAnswer: 3, explanation: "Gerilmiş halatın kopması hâlinde kamçı gibi savrulduğu bölgedir; güvertede işaretlenir ve operasyon sırasında bu alanda durulmaz.", category: "Palamar" },
  { id: 100, question: "Halatın kopma yükü 400 kN ve emniyet katsayısı 5 ise emniyetli çalışma yükü kaç kN'dur?", options: ["200 kN", "40 kN", "80 kN", "100 kN"], correctAnswer: 2, explanation: "SWL = kopma yükü/emniyet katsayısı = 400/5 = 80 kN.", category: "Palamar" },
  { id: 101, question: "Mooring vinci otomatik moda alındığında ne yapar?", options: ["Halatı sabit tutar", "Gerginlik değiştikçe halatı kendiliğinden boşlar veya vira eder", "Halatı keser", "Vinci kilitler"], correctAnswer: 1, explanation: "Otomatik gerginlik modu gelgit ve draft değişimine uyum sağlar; ancak halat kaymalarına yol açabileceği için birçok terminalde yasaktır.", category: "Palamar" },
  { id: 102, question: "Halat üzerindeki 'chafing' hasarı neyi ifade eder?", options: ["Donmayı", "Ultraviyole yıpranmasını", "Kimyasal yıpranmayı", "Sürtünme kaynaklı aşınmayı"], correctAnswer: 3, explanation: "Fairlead ve kenar temaslarında oluşur; koruyucu kılıf ve düzgün yönlendirme ile önlenir, aşınmış bölüm kesilip halat yenilenir.", category: "Palamar" },
  { id: 103, question: "Sentetik halatlarda 'rat tail' ve renk değişimi neyi gösterir?", options: ["Aşırı yüklenme veya iç lif hasarını", "Yeni halatı", "Doğru bakımı", "Normal kullanımı"], correctAnswer: 0, explanation: "Sertleşme, tüylenme ve düzensiz çap iç yapının bozulduğunu gösterir; halat hizmetten çıkarılmalıdır.", category: "Palamar" },
  { id: 104, question: "İzbarço (bowline) düğümünün temel özelliği nedir?", options: ["Halatı kısaltır", "Yük altında sıkışır ve çözülmez", "Sabit büyüklükte bir ilmek oluşturur ve yük kalktığında kolay çözülür", "İki halatı kalıcı birleştirir"], correctAnswer: 2, explanation: "İzbarço güvenilir bir ilmek düğümüdür; ancak titreşimli yüklerde gevşeyebileceği için ucu emniyete alınır.", category: "Düğümler" },
  { id: 105, question: "Camadan bağı (reef knot) hangi amaçla kullanılmamalıdır?", options: ["Branda bağlamak", "Paket sarmak", "İki ucu birbirine bağlamak", "Farklı kalınlıktaki iki halatı yük altında birleştirmek"], correctAnswer: 3, explanation: "Reef knot yalnızca aynı kalınlıktaki halatların gergin olmayan uçlarını bağlar; yük altında veya farklı kalınlıkta kayarak açılır.", category: "Düğümler" },
  { id: 106, question: "Kropi bağı (sheet bend) hangi durumda tercih edilir?", options: ["Aynı kalınlıkta iki halat için", "Farklı kalınlıktaki iki halatı birleştirmek için", "Halatı babaya bağlamak için", "İlmek yapmak için"], correctAnswer: 1, explanation: "İnce halat kalın halatın ilmeğinden geçirilir; kayma riskine karşı çift kropi (double sheet bend) daha güvenlidir.", category: "Düğümler" },
  { id: 107, question: "Kazık bağı (clove hitch) hangi durumda güvenilir değildir?", options: ["Geçici bağlarda", "Direk üzerinde", "Fenderi babaya bağlarken", "Yük yönü sürekli değiştiğinde"], correctAnswer: 3, explanation: "Dönen veya yön değiştiren yüklerde gevşer; kalıcı bağlarda üzerine yarım anele veya ek bağ atılmalıdır.", category: "Düğümler" },
  { id: 108, question: "Sekiz düğümünün (figure-of-eight) amacı nedir?", options: ["Halatı kısaltmak", "İki halatı birleştirmek", "Halatın ucunun makaradan/deliğinden kaçmasını önlemek", "İlmek yapmak"], correctAnswer: 2, explanation: "Bir stopper düğümüdür; düz düğüme göre yük altında daha kolay çözülür ve halatı daha az zayıflatır.", category: "Düğümler" },
  { id: 109, question: "Halatta yapılan bir düğüm kopma mukavemetini yaklaşık ne kadar azaltır?", options: ["%80–90", "Etkilemez", "%5–10", "%30–50"], correctAnswer: 3, explanation: "Düğüm noktasındaki keskin dönüş ve sıkışma lifleri zorlar; bu yüzden kalıcı bağlantılarda dikiş (splice) tercih edilir.", category: "Düğümler" },
  { id: 110, question: "Dikiş (splice) neden düğüme tercih edilir?", options: ["Halatın kopma mukavemetinin çok daha büyük bölümünü koruduğu için", "Daha güzel göründüğü için", "Daha kısa olduğu için", "Daha hızlı yapıldığı için"], correctAnswer: 0, explanation: "İyi yapılmış bir göz dikişi mukavemetin yaklaşık %90'ını korur; düğümde bu oran yarıya kadar düşebilir.", category: "Düğümler" },
  { id: 111, question: "Sağ devirli tek pervanede tornistanda geminin kıçı hangi yöne kaçar?", options: ["Kaçmaz", "Rüzgâr yönüne", "Sancağa", "İskeleye"], correctAnswer: 3, explanation: "Transverse thrust (yan itki) nedeniyle sağ devirli pervanede tornistanda kıç iskeleye yürür; bu etki yanaşma manevralarında kullanılır.", category: "Manevra" },
  { id: 112, question: "Squat etkisi neyi ifade eder?", options: ["Pervane titreşimini", "Geminin meyil etmesini", "Sığ suda hız nedeniyle geminin çökmesi ve trim değiştirmesini", "Geminin savrulmasını"], correctAnswer: 2, explanation: "Gövde altında hızlanan su basıncı düşürür; gemi çöker ve genellikle baş tarafa trim alır. Hız düşürmek en etkili önlemdir.", category: "Manevra" },
  { id: 113, question: "Squat etkisi hıza göre nasıl değişir?", options: ["Yaklaşık hızın karesiyle orantılı", "Hızdan bağımsız", "Hızla ters orantılı", "Hızla doğru orantılı"], correctAnswer: 0, explanation: "Squat ≈ hızın karesiyle artar; bu yüzden hızı yarıya indirmek çökmeyi yaklaşık dörtte bire düşürür.", category: "Manevra" },
  { id: 114, question: "Sığ su etkisi (shallow water effect) manevrayı nasıl değiştirir?", options: ["Durma mesafesi kısalır", "Etkisi yoktur", "Dönüş çapı küçülür", "Dönüş çapı büyür ve gemi dümene geç tepki verir"], correctAnswer: 3, explanation: "Su akışı kısıtlandığından gemi ağırlaşmış gibi davranır; dönüş yarıçapı artar, durma mesafesi uzar ve titreşim artabilir.", category: "Manevra" },
  { id: 115, question: "Advance (ilerleme) terimi dönüş dairesinde neyi ifade eder?", options: ["Toplam dönüş çapını", "Durma mesafesini", "Geminin yanal kaymasını", "Dümen basıldıktan sonra ilk rota doğrultusunda alınan mesafeyi"], correctAnswer: 3, explanation: "Advance, dümenin basıldığı andan itibaren orijinal rota yönünde katedilen mesafedir; transfer ise buna dik yöndeki kaymadır.", category: "Manevra" },
  { id: 116, question: "Dönüş dairesinde 'tactical diameter' ne zaman ölçülür?", options: ["Dümen ortalandığında", "Rota 90° değiştiğinde", "Rota 180° değiştiğinde ölçülen enine mesafe", "Dönüş tamamlandığında"], correctAnswer: 2, explanation: "Taktik çap, gemi ilk rotasından 180° döndüğünde ölçülen yanal mesafedir; manevra karakteristikleri levhasında yer alır.", category: "Manevra" },
  { id: 117, question: "Pivot point (dönme noktası) yol alan bir gemide nerede bulunur?", options: ["Tam ortada", "Pervanede", "Kıçta", "Baştan yaklaşık gemi boyunun 1/4'ü kadar geride"], correctAnswer: 3, explanation: "İleri yolda dönme noktası baş tarafa yakındır (yaklaşık L/4); tornistanda kıça doğru kayar. Manevra hissini belirleyen temel kavramdır.", category: "Manevra" },
  { id: 118, question: "Interaction (etkileşim) etkisi hangi durumda belirginleşir?", options: ["Açık denizde", "Dar kanalda iki geminin yakın mesafede geçmesinde", "Demirdeyken", "Rıhtımda"], correctAnswer: 1, explanation: "Basınç alanları birbirini iter ve çeker; baş savrulması ve emme etkisi çarpışmaya yol açabilir. Hız düşürmek ve mesafe artırmak temel önlemdir.", category: "Manevra" },
  { id: 119, question: "Bank effect (kıyı etkisi) geminin başını nasıl etkiler?", options: ["Başı kıyıdan uzağa iter, kıçı kıyıya çeker", "Etkilemez", "Yalnızca hızı düşürür", "Başı kıyıya doğru iter"], correctAnswer: 0, explanation: "Kıyı tarafındaki basınç artışı başı dışarı iterken kıçtaki emme kıçı kıyıya çeker; dümenle sürekli düzeltme gerekir.", category: "Manevra" },
  { id: 120, question: "Baş iticinin (bow thruster) etkinliği hangi durumda azalır?", options: ["Rüzgâr yokken", "Derin suda", "Gemi durmuşken", "Gemi ileri yol aldıkça"], correctAnswer: 3, explanation: "Yaklaşık 3–4 knot üzerinde tünel çıkışındaki akım itkiyi büyük ölçüde etkisizleştirir; iticiler düşük hızda kullanılır.", category: "Manevra" },
  { id: 121, question: "'Hard a starboard' komutu ne anlama gelir?", options: ["Sancağa 10 derece bas", "Dümeni sancağa 5 derece bas", "Dümeni sancağa sonuna kadar bas", "Rotayı sancakta tut"], correctAnswer: 2, explanation: "Dümen sancak tarafına tam (genellikle 35°) basılır; komut aynen tekrarlanarak uygulanır ve yerine getirildiğinde bildirilir.", category: "Dümen Komutları" },
  { id: 122, question: "'Midships' komutu ne demektir?", options: ["Rotayı koru", "Tornistan yap", "Gemiyi durdur", "Dümeni ortala"], correctAnswer: 3, explanation: "Dümen sıfır dereceye getirilir; dönüşü yavaşlatmak veya bitirmek için kullanılır.", category: "Dümen Komutları" },
  { id: 123, question: "'Steady as she goes' komutu ne ister?", options: ["Mevcut pruva istikametinde seyre devam", "Dümeni tam bas", "Tornistan", "Demir at"], correctAnswer: 0, explanation: "Komutun verildiği andaki pruva yönünde seyredilir; dümenci mevcut rotayı okuyarak teyit eder.", category: "Dümen Komutları" },
  { id: 124, question: "Dümen komutlarının tekrar edilmesi (repeat back) neden zorunludur?", options: ["Kayıt için", "Gürültü için", "Gelenek olduğu için", "Yanlış anlaşılmayı önlemek ve komutun doğru uygulandığını doğrulamak için"], correctAnswer: 3, explanation: "Dümenci komutu aynen tekrarlar, uygular ve tamamlandığında bildirir; kapalı döngü iletişim köprüüstü emniyetinin temelidir.", category: "Dümen Komutları" },
  { id: 125, question: "Otomatik pilottan el dümenine geçiş hangi durumda derhal yapılmalıdır?", options: ["Demirde", "Açık denizde", "Trafik yoğunlaştığında, dar sularda ve manevra gerektiğinde", "Gece"], correctAnswer: 2, explanation: "SOLAS V/24: kısıtlı sularda veya tehlike durumunda el dümenine geçiş anında yapılabilecek şekilde hazır bulundurulur ve düzenli test edilir.", category: "Dümen Komutları" },
  { id: 126, question: "Köprüüstü vardiyasında gözcünün (lookout) temel görevi nedir?", options: ["Telsiz dinlemek", "Yalnızca gözlem yaparak görme ve işitme yoluyla tehlikeleri bildirmek", "Dümen tutmak", "Jurnal yazmak"], correctAnswer: 1, explanation: "COLREG Kural 5: gözcü başka görevle meşgul edilemez; gündüz tek başına vardiya ancak belirli koşullarda ve gözcü hazırken mümkündür.", category: "Vardiya" },
  { id: 127, question: "Vardiya zabiti hangi durumda kaptanı derhal çağırmalıdır?", options: ["Vardiya bitiminde", "Yakıt azaldığında", "Yalnızca çarpışma olduğunda", "Görüş bozulduğunda, trafik şüphe yarattığında veya daimî emirlerdeki eşikler aşıldığında"], correctAnswer: 3, explanation: "Kaptanı çağırmak zayıflık değil prosedürdür; çağrı yapılırken de zabit gerekli emniyet tedbirini almayı sürdürür.", category: "Vardiya" },
  { id: 128, question: "Vardiya devri sırasında devreden zabitin sorumluluğu ne zaman biter?", options: ["Devralan zabit durumu tam olarak kavrayıp devri kabul ettiğinde", "Saat başında", "Jurnal imzalandığında", "Kapıdan çıktığında"], correctAnswer: 0, explanation: "Devralan zabit gözü karanlığa alışmadan veya durumu kavramadan devir tamamlanmaz; manevra sırasında devir yapılmaz.", category: "Vardiya" },
  { id: 129, question: "Vardiya jurnaline (deck log) kaydedilmesi gereken bilgi hangisidir?", options: ["Yalnızca yük", "Yalnızca hava durumu", "Konum, rota/hız değişiklikleri, önemli olaylar ve verilen emirler", "Yalnızca yakıt"], correctAnswer: 2, explanation: "Jurnal hukuki bir kayıttır; olay sonrası incelemelerde en güçlü delildir ve gerçeğe uygun, zamanında tutulmalıdır.", category: "Vardiya" },
  { id: 130, question: "Kısıtlı görüşte vardiya tutarken ilk alınacak önlem nedir?", options: ["Otomatik pilotta kalmak", "Işıkları söndürmek", "Hızı artırmak", "Emniyetli hıza inmek, radarı çalıştırmak, sis düdüğü vermek ve gözcü artırmak"], correctAnswer: 3, explanation: "COLREG Kural 19: makine manevraya hazır tutulur, gerekirse yol kesilir; radar plotlaması sistematik biçimde sürdürülür.", category: "Vardiya" },
  { id: 131, question: "COLREG'e göre 'yol veren gemi' (give-way vessel) ne yapmalıdır?", options: ["Rotasını korumalı", "Erken ve belirgin biçimde manevra yaparak diğer geminin önünden geçmekten kaçınmalı", "Hızlanmalı", "Beklemeli"], correctAnswer: 1, explanation: "Kural 16: yol veren gemi mümkün olduğunca erken ve kararlı aksiyon alır; mümkünse diğer geminin kıçından geçecek şekilde manevra yapar.", category: "COLREG" },
  { id: 132, question: "İki motorlu gemi çapraz (crossing) durumdayken hangisi yol verir?", options: ["İskelesinde diğer gemiyi gören", "Küçük olan", "Yavaş olan", "Sancağında diğer gemiyi gören"], correctAnswer: 3, explanation: "COLREG Kural 15: diğer gemiyi sancak tarafında gören gemi yol verir ve mümkünse onun önünden geçmez.", category: "COLREG" },
  { id: 133, question: "Motorlu bir gemi ile yelkenli gemi karşılaştığında kim yol verir?", options: ["Rüzgâr üstündeki", "Yelkenli", "Motorlu gemi", "Büyük olan"], correctAnswer: 2, explanation: "Kural 18: yol alan motorlu gemi, yelkenli gemiye ve balıkçılıkla meşgul gemiye yol verir. Ancak geçme durumunda Kural 13 önceliklidir.", category: "COLREG" },
  { id: 134, question: "Manevra kabiliyeti kısıtlı gemi gündüz hangi işareti gösterir?", options: ["İki koni", "Silindir", "Bir siyah küre", "Yukarıdan aşağıya küre-baklava-küre şeklinde üç işaret"], correctAnswer: 3, explanation: "Kural 27: manevra kabiliyeti kısıtlı gemi küre-baklava-küre; gece ise kırmızı-beyaz-kırmızı çevresel fener gösterir.", category: "COLREG" },
  { id: 135, question: "Draftı nedeniyle kısıtlı gemi gündüz hangi işareti gösterir?", options: ["Bir siyah silindir", "İki küre", "Bir koni", "Üç küre"], correctAnswer: 0, explanation: "Kural 28: draftı nedeniyle kısıtlı gemi bir siyah silindir; gece üç kırmızı çevresel fener gösterir.", category: "COLREG" },
  { id: 136, question: "Kumanda edemeyen (not under command) gemi gece hangi fenerleri gösterir?", options: ["İki beyaz fener", "Kırmızı-beyaz-kırmızı", "Üç kırmızı", "İki kırmızı çevresel fener"], correctAnswer: 3, explanation: "Kural 27: düşey iki kırmızı çevresel fener; yol alıyorsa ayrıca borda ve kıç fenerleri gösterilir. Gündüz iki siyah küre kullanılır.", category: "COLREG" },
  { id: 137, question: "Trolle balıkçılık yapan gemi gündüz hangi işareti gösterir?", options: ["Bir silindir", "Üç küre", "İki koni, tepe noktaları birleşik", "Bir küre"], correctAnswer: 2, explanation: "Kural 26: balıkçılıkla meşgul gemi tepe noktaları birleşik iki koni gösterir; trol dışı balıkçılıkta ayrıca ağ yönünü belirten koni eklenir.", category: "COLREG" },
  { id: 138, question: "Ağır havada 'heave to' manevrası neyi hedefler?", options: ["Gemiyi denize göre en az zorlanacağı bir açı ve asgari hızda tutmayı", "Demirlemeyi", "Tornistan gitmeyi", "Hızlı ilerlemeyi"], correctAnswer: 0, explanation: "Baş dalgalara belirli bir açıyla tutularak asgari yolla ilerlenir; slamming, yeşil su ve aşırı yalpa azaltılır.", category: "Ağır Hava" },
  { id: 139, question: "Ağır havada baş dalgada hız düşürmenin temel gerekçesi nedir?", options: ["Konfor", "Gürültü", "Yakıt tasarrufu", "Slamming ve baş üstü su alma nedeniyle oluşan yapısal zorlanmayı azaltmak"], correctAnswer: 3, explanation: "Baş dip vurması yerel gerilmeleri hızla artırır; hız ve rota ayarı en etkili ve en hızlı uygulanabilir önlemdir.", category: "Ağır Hava" },
  { id: 140, question: "Takip eden denizde (following sea) hangi tehlike öne çıkar?", options: ["Buzlanma", "Sis", "Slamming", "Broaching ve dümen etkinliğinin azalması"], correctAnswer: 3, explanation: "Dalga tepesindeyken dümen etkinliği düşer ve gemi denize enine savrulabilir; hız ile dalga hızı arasındaki ilişki yönetilmelidir.", category: "Ağır Hava" },
  { id: 141, question: "Ağır havada güverte çalışması için temel kural nedir?", options: ["Yalnızca kaptan yapar", "Her koşulda sürdürülür", "Güvenli hâle gelene kadar ertelenir; zorunluysa can halatı ve gözcü ile yapılır", "Yalnızca gece yapılır"], correctAnswer: 2, explanation: "Güverteye çıkış kaptan izniyle olur; rota/hız değiştirilerek gemi hareketi azaltılır ve personel emniyet donanımı kullanır.", category: "Ağır Hava" },
  { id: 142, question: "Ağır hava öncesi yapılması gereken hazırlık nedir?", options: ["Yalnızca hız artırmak", "Yalnızca demir hazırlamak", "Yalnızca hava raporu almak", "Tüm açıklıkların kapatılması, bağlamaların kontrolü ve serbest yüzeylerin azaltılması"], correctAnswer: 3, explanation: "Ambar kapakları, havalandırmalar ve su geçirmez kapılar kapatılır; tanklar ya tam doldurulur ya boşaltılır ve güverte donanımı ek bağlanır.", category: "Ağır Hava" },
  { id: 143, question: "Buzlanma tehlikesi olan bölgelerde alınacak önlem nedir?", options: ["Buzun erimesini beklemek", "Üst yapı ve güvertedeki buzu düzenli temizlemek ve rota/hız değiştirmek", "Balast almak", "Demirlemek"], correctAnswer: 1, explanation: "Biriken buz KG'yi yükselterek stabiliteyi bozar; temizlik yapılamıyorsa buzlanma bölgesinden çıkacak şekilde rota değiştirilir.", category: "Ağır Hava" },
  { id: 144, question: "Su alma (flooding) durumunda ilk yapılması gereken nedir?", options: ["Alarm vermek, bölmeyi izole etmek ve su girişinin yerini/miktarını tespit etmek", "Demir atmak", "Hız artırmak", "Gemiyi terk etmek"], correctAnswer: 0, explanation: "Su geçirmez kapılar kapatılır, hasar kontrol ekibi hasarı sınırlandırır; bu arada stabilite ve mukavemet etkisi hesaplanır.", category: "Acil Durum" },
  { id: 145, question: "Karaya oturma (grounding) sonrası ilk adım nedir?", options: ["Demir atmak", "Yükü boşaltmak", "Derhal tornistan yapmak", "Makineyi durdurup hasar, su girişi ve çevre kirliliğini değerlendirmek"], correctAnswer: 3, explanation: "Hemen kurtulmaya çalışmak yırtığı büyütebilir ve batmaya yol açabilir; iskandil, tank ölçümleri ve gelgit değerlendirmesi yapılır.", category: "Acil Durum" },
  { id: 146, question: "Karaya oturmadan sonra tank ölçümlerinin (sounding) hemen alınmasının nedeni nedir?", options: ["Yük hesabı", "Yakıt hesabı", "Su girişini ve hasarlı bölmeleri tespit etmek", "Trim hesabı"], correctAnswer: 2, explanation: "Tank ve bilge ölçümlerindeki artış hasarın yerini ve büyüklüğünü gösterir; karşılaştırma için kayıt zaman damgalı tutulur.", category: "Acil Durum" },
  { id: 147, question: "Çatışma (collision) sonrası gemiler neden hemen ayrılmamalıdır?", options: ["Yakıt nedeniyle", "Manevra nedeniyle", "Hukuki nedenle", "Ayrılma yaranın açılmasına ve hızlı su almaya yol açabileceği için"], correctAnswer: 3, explanation: "Karşı gemi yarayı geçici olarak tıkayabilir; ayrılma kararı ancak stabilite ve su alma değerlendirmesinden sonra verilir.", category: "Acil Durum" },
  { id: 148, question: "Dümen arızasında ilk yapılması gereken nedir?", options: ["Yedek dümen sistemine geçmek, uygun işaret/fenerleri göstermek ve trafiği uyarmak", "Demir atmak", "Hız artırmak", "Makineyi durdurmak"], correctAnswer: 0, explanation: "Acil dümen istasyonu devreye alınır; gemi kumanda edemez duruma düşerse NUC işaretleri gösterilir ve VHF'ten yakın trafiğe bildirilir.", category: "Acil Durum" },
  { id: 149, question: "Karadan yardım isterken (towage) en kritik bilgi nedir?", options: ["Mürettebat listesi", "Yük fiyatı", "Yakıt miktarı", "Geminin konumu, durumu, draft/deplasman ve sürüklenme yönü"], correctAnswer: 3, explanation: "Kurtarma planlaması için gemi büyüklüğü, hasar durumu, sürüklenme hızı ve hava tahmini gerekir; ayrıca kirlilik riski bildirilir.", category: "Acil Durum" },
  { id: 150, question: "Yedekleme (towing) hattında chafing önlemi neden kritiktir?", options: ["Hız için", "Görüntü için", "Loça ve kenar sürtünmesinin halatı kısa sürede kesebilmesi nedeniyle", "Ağırlık için"], correctAnswer: 2, explanation: "Sürekli hareket eden hat temas noktasında hızla aşınır; koruyucu kılıf kullanılır ve hat düzenli olarak biraz kaydırılır.", category: "Acil Durum" },
  { id: 151, question: "Can kurtarma botunun düzenli çalıştırılmasının amacı nedir?", options: ["Yakıt tazelemek", "Motor, dümen ve serbest bırakma donanımının çalışır durumda olduğunu doğrulamak", "Boyamak", "Ağırlığını ölçmek"], correctAnswer: 1, explanation: "Haftalık motor çalıştırma ve düzenli indirme testleri, gerçek acil durumda donanımın çalışacağını güvence altına alır.", category: "Can Kurtarma" },
  { id: 152, question: "Can salı istifleme yerinin seçiminde temel kriter nedir?", options: ["Ağırlık dağılımı", "Boya kalınlığı", "Estetik", "Her iki bordadan hızlı erişim ve serbestçe suya bırakılabilme"], correctAnswer: 3, explanation: "Sal, üzerine engel gelmeyecek ve HRU ile serbestçe yüzebilecek şekilde yerleştirilir; erişim yolları her zaman açık tutulur.", category: "Can Kurtarma" },
  { id: 153, question: "Can salı bindirme merdiveni (embarkation ladder) hangi durumda kullanılır?", options: ["Sal veya bota doğrudan geçilemediğinde denize inmek için", "Yük almak için", "Kılavuz için", "Yalnızca limanda"], correctAnswer: 0, explanation: "Merdiven su hattına kadar uzanmalı ve gemi meyilliyken de kullanılabilmelidir; düzenli olarak muayene edilir.", category: "Can Kurtarma" },
  { id: 154, question: "Can salı içindeki deniz demirinin (sea anchor) işlevi nedir?", options: ["Su toplamak", "Salı demirlemek", "Sürüklenmeyi yavaşlatmak ve salı dalgaya karşı stabil tutmak", "Sal ağırlığını artırmak"], correctAnswer: 2, explanation: "Sürüklenmeyi azaltarak kaza mahalline yakın kalınmasını sağlar ve salın devrilme eğilimini düşürür.", category: "Can Kurtarma" },
  { id: 155, question: "Can salında sinyal aynası (heliograph) ne zaman etkilidir?", options: ["Sisli havada", "Yağmurda", "Gece", "Güneşli havada uzaktaki gemi/uçağa yansıma göndermek için"], correctAnswer: 3, explanation: "Güneş ışığını hedefe yansıtarak çok uzaktan fark edilebilir; pil gerektirmediği için sınırsız kullanılabilir.", category: "Can Kurtarma" },
  { id: 156, question: "Gemi boyası uygulanmadan önce yüzey hazırlığının önemi nedir?", options: ["Renk için", "Pas ve tuzun temizlenmemesi boyanın kısa sürede kalkmasına yol açtığı için", "Kalınlık için", "Kuruma için"], correctAnswer: 1, explanation: "Yüzey hazırlığı boya ömrünün en belirleyici etkenidir; tuz kalıntısı ve nem altında uygulanan boya kabarır.", category: "Bakım" },
  { id: 157, question: "Katodik koruma sistemi gemiyi neye karşı korur?", options: ["Çarpmaya", "Aşınmaya", "Yosunlanmaya", "Galvanik korozyona"], correctAnswer: 3, explanation: "Çinko/alüminyum anotlar veya empresli akım sistemi, çelik gövde yerine kendisi kurban olarak korozyonu önler.", category: "Bakım" },
  { id: 158, question: "Antifouling boyanın işlevi nedir?", options: ["Görünüm sağlamak", "Paslanmayı önlemek", "Gövdeye deniz canlılarının yapışmasını engelleyerek sürtünmeyi düşürmek", "Yalıtım sağlamak"], correctAnswer: 2, explanation: "Yosun ve midye birikimi sürtünmeyi ve yakıt tüketimini belirgin biçimde artırır; boya ayrıca AFS Sözleşmesi'ne uygun olmalıdır.", category: "Bakım" },
  { id: 159, question: "Güverte donanımının düzenli greslenmesi neden gereklidir?", options: ["Ağırlık için", "Ses için", "Görüntü için", "Korozyonu ve sürtünme kaynaklı aşınmayı azaltarak arızayı önlemek için"], correctAnswer: 3, explanation: "Vinç yatakları, makara ve loçalar planlı bakım sistemine göre yağlanır; ihmal, kritik anda donanım arızasına yol açar.", category: "Bakım" },
  { id: 160, question: "Tel halatın hizmetten çıkarılmasını gerektiren durum hangisidir?", options: ["Belirli bir uzunlukta izin verilen sayıdan fazla kopmuş tel bulunması", "Rengin solması", "Hafif yağlanma", "Hafif tozlanma"], correctAnswer: 0, explanation: "Kopan tel sayısı, çap azalması, korozyon ve ezilme kriterlerinden herhangi biri aşıldığında halat değiştirilir.", category: "Bakım" },
  { id: 161, question: "Ambar ve tank içi boya işlerinde en kritik emniyet önlemi nedir?", options: ["Sıcaklık kontrolü", "Nem ölçümü", "Aydınlatma", "Sürekli havalandırma, gaz ölçümü ve uygun solunum koruması"], correctAnswer: 3, explanation: "Solvent buharı hem patlayıcı hem zehirlidir; kapalı mahal giriş izni ve sürekli izleme zorunludur.", category: "İş Emniyeti" },
  { id: 162, question: "Güvertede çalışırken kişisel koruyucu donanımın belirlenmesi neye dayanır?", options: ["Vardiya saatine", "Kişisel tercihe", "İş için yapılan risk değerlendirmesine", "Hava durumuna"], correctAnswer: 2, explanation: "Her iş öncesi risk değerlendirmesi tehlikeleri belirler ve gerekli KKD'yi tanımlar; toolbox talk'ta ekiple paylaşılır.", category: "İş Emniyeti" },
  { id: 163, question: "Kılavuz çarmıhı (pilot ladder) kurulumunda en kritik nokta nedir?", options: ["Basamakların yatay olması, halatların hasarsız olması ve doğru yükseklikte donatılması", "Ağırlığı", "Uzunluğu", "Rengi"], correctAnswer: 0, explanation: "Hatalı donatılmış kılavuz çarmıhı ölümcül kazalara yol açar; kurulum sorumlu bir zabitin gözetiminde yapılır ve düzenli muayene edilir.", category: "İş Emniyeti" },
  { id: 164, question: "Kılavuz alma/verme sırasında güvertede bulunması gereken donanım nedir?", options: ["Yalnızca merdiven", "Yalnızca eldiven", "Yalnızca fener", "Can simidi (ışıklı), halat ve telsizli sorumlu zabit"], correctAnswer: 3, explanation: "Düşme hâlinde derhal müdahale edilebilmelidir; ayrıca aydınlatma ve rüzgâr altı borda seçimi manevrayla koordine edilir.", category: "İş Emniyeti" },
  { id: 165, question: "Vinç ile yük kaldırırken personelin yükün altında bulunmaması neden şarttır?", options: ["Gürültü nedeniyle", "Elektrik nedeniyle", "Görüş engellediği için", "Donanım arızasında yükün düşerek ölümcül yaralanmaya yol açması nedeniyle"], correctAnswer: 3, explanation: "Askıdaki yük daima potansiyel tehlikedir; çalışma alanı işaretlenir ve yükün hareket edeceği güzergâh boşaltılır.", category: "İş Emniyeti" },
  { id: 166, question: "ISM kapsamında planlı bakım sisteminin (PMS) amacı nedir?", options: ["Denetim geçmek", "Maliyet düşürmek", "Kritik ekipmanın arıza öncesi bakımını planlayarak güvenilirliği sürdürmek", "Personel azaltmak"], correctAnswer: 2, explanation: "PMS bakım aralıklarını, yedek parça takibini ve kayıtları yönetir; kritik ekipman listesi risk değerlendirmesine dayanır.", category: "ISM/ISPS" },
  { id: 167, question: "Kritik ekipman (critical equipment) nasıl tanımlanır?", options: ["En yeni ekipman", "En sık kullanılan ekipman", "En pahalı ekipman", "Arızası can, gemi veya çevre için ani tehlike doğurabilecek ekipman"], correctAnswer: 3, explanation: "Dümen, ana makine, jeneratör, yangın pompası gibi sistemler kritik kabul edilir; bunlar için yedekleme ve test rejimi tanımlanır.", category: "ISM/ISPS" },
  { id: 168, question: "Gemi güvenlik devriyesinin (security round) amacı nedir?", options: ["Temizlik kontrolü", "Yetkisiz giriş, şüpheli paket ve güvenlik ihlallerinin tespiti", "Yük kontrolü", "Bakım kontrolü"], correctAnswer: 1, explanation: "Kritik alanlar, erişim noktaları ve güverte düzenli aralıklarla kontrol edilir; bulgular kayda geçirilerek SSO'ya raporlanır.", category: "ISM/ISPS" },
  { id: 169, question: "Limanda gemiye giriş kontrolünde temel uygulama nedir?", options: ["Kimlik kontrolü, ziyaretçi kaydı ve gerektiğinde arama", "Yalnızca acenteyi kaydetmek", "Kontrol yapmamak", "Herkesi kabul etmek"], correctAnswer: 0, explanation: "ISPS gemi güvenlik planı erişim kontrolünü tanımlar; güvenlik seviyesi yükseldikçe kontrol ve arama oranı artar.", category: "ISM/ISPS" },
  { id: 170, question: "SMS'te 'kaptanın gözden geçirmesi' (master's review) neyi kapsar?", options: ["Yalnızca personel izinlerini", "Yalnızca bakım listesini", "Yalnızca yük planını", "Sistemin gemide etkin uygulanıp uygulanmadığına dair değerlendirme ve iyileştirme önerilerini"], correctAnswer: 3, explanation: "Kaptanın değerlendirmesi şirkete raporlanır ve yönetimin gözden geçirmesine girdi oluşturur; sistemin gemi gerçeğine uyumunu sağlar.", category: "SMS" },
  { id: 171, question: "Gemi–kara arayüzünde (ship/shore interface) emniyetin temeli nedir?", options: ["Düşük maliyet", "Hızlı operasyon", "Açık, teyitli ve kesintisiz iletişim", "Az personel"], correctAnswer: 2, explanation: "Kontrol listeleri, ortak dil ve acil durdurma sinyali önceden kararlaştırılır; iletişim kopması operasyonun durdurulmasını gerektirir.", category: "SMS" },
  { id: 172, question: "Halat çapı arttıkça kopma yükü yaklaşık nasıl değişir?", options: ["Değişmez", "Azalır", "Doğrusal artar", "Çapın karesiyle artar"], correctAnswer: 3, explanation: "Kesit alanı çapın karesiyle orantılı olduğundan kopma yükü de yaklaşık aynı oranda artar; çapı iki katına çıkan halat yaklaşık dört kat yük taşır.", category: "Palamar" },
  { id: 173, question: "Çapı 24 mm olan bir halatın kopma yükü 200 kN ise 48 mm çaplı aynı tip halatın kopma yükü yaklaşık kaç kN olur?", options: ["800 kN", "1,600 kN", "400 kN", "600 kN"], correctAnswer: 0, explanation: "Kopma yükü ≈ çapın karesiyle orantılıdır: (48/24)² = 4 → 200 × 4 = 800 kN.", category: "Palamar" },
  { id: 174, question: "Demir zincirinin kilit bağlantılarında kullanılan Kenter kilidi ne sağlar?", options: ["Zinciri kilitler", "Demiri tutar", "Zinciri kısaltır", "İki zincir bölümünü zincir baklası profilinde birleştirir"], correctAnswer: 3, explanation: "Kenter kilidi loçadan ve barbotenden sorunsuz geçecek profildedir; her kilit bağlantısı boyalı işaretlerle ayrıca belirtilir.", category: "Demirleme" },
  { id: 175, question: "Zincir kilit işaretlerinin boyanması neden önemlidir?", options: ["Ağırlık için", "Görünüm için", "Suya verilen kaloma miktarının anında okunabilmesi için", "Korozyon için"], correctAnswer: 2, explanation: "Bakla boyaları ve tel sarımlar kaç kilit verildiğini gösterir; gece ve acil durumda hızlı okuma sağlar.", category: "Demirleme" },
  { id: 176, question: "Demir ıskarçası (foul anchor) durumu nedir?", options: ["Demirin paslanması", "Zincirin demire veya dipteki bir cisme dolanması", "Demirin kaybolması", "Zincirin kopması"], correctAnswer: 1, explanation: "Zincir dolanması demirin tutmasını bozar ve demir alma sırasında ciddi zorluk çıkarır; gerekirse dalgıç veya ek manevra gerekir.", category: "Demirleme" },
  { id: 177, question: "Rıhtıma yanaşırken rüzgâr rıhtımdan denize doğru esiyorsa ne beklenir?", options: ["Manevra kolaylaşır", "Etkisi olmaz", "Gemi kendiliğinden rıhtıma yanaşır", "Gemi rıhtımdan uzaklaşma eğilimi gösterir, römorkör/itici desteği gerekebilir"], correctAnswer: 3, explanation: "Off-berth rüzgârda yanaşma zorlaşır; genellikle daha büyük yaklaşma açısı, itici ve römorkör kullanımı ile halatların erken verilmesi gerekir.", category: "Manevra" },
  { id: 178, question: "Rıhtıma yaklaşırken uygun yaklaşma hızı neye göre belirlenir?", options: ["Fender ve rıhtım dayanımını aşmayacak, kontrolü kaybetmeyecek en düşük hız", "Sabit 5 knot", "Akıntı hızı", "Mümkün olan en yüksek hız"], correctAnswer: 0, explanation: "Büyük gemilerde yanaşma hızı tipik olarak 0.1–0.15 m/s mertebesindedir; aşırı hız rıhtım ve gövde hasarına yol açar.", category: "Manevra" },
  { id: 179, question: "Römorkörle çalışırken 'girting' (kapsize) riski nedir?", options: ["Römorkörün karaya oturması", "Yakıt bitmesi", "Römorkörün yanlamasına çekilerek devrilmesi", "Halatın kopması"], correctAnswer: 2, explanation: "Yedek hattı römorkörün enine gelirse tekne devrilebilir; bu yüzden hız sınırlanır, hat açısı izlenir ve hızlı bırakma donanımı hazır tutulur.", category: "Manevra" },
  { id: 180, question: "Römorkör bağlantısında hızlı bırakma (quick release) donanımı neden şarttır?", options: ["Halat korumak için", "Kayıt için", "Zaman kazanmak için", "Tehlike anında yedek hattının anında serbest bırakılabilmesi için"], correctAnswer: 3, explanation: "Girting veya ani gerginlik durumunda hat saniyeler içinde bırakılabilmelidir; donanım düzenli test edilir.", category: "Manevra" },
  { id: 181, question: "Dar kanalda geçiş yapılırken hız neden sınırlanır?", options: ["Yakıt tasarrufu için", "Squat, etkileşim ve kıyı etkisini azaltmak ve kıyı erozyonunu önlemek için", "Gürültü için", "Radar için"], correctAnswer: 1, explanation: "Hız düştükçe basınç etkileri belirgin biçimde azalır; ayrıca ani manevra ihtiyacında tepki için zaman kazanılır.", category: "Manevra" },
  { id: 182, question: "Gemi tornistan yaparken dümenin etkinliği nasıl değişir?", options: ["Değişmez", "Ters yönde artar", "Artar", "Belirgin biçimde azalır"], correctAnswer: 3, explanation: "Pervane akımı artık dümene çarpmadığından dümen etkinliği düşer; tornistanda yön kontrolü büyük ölçüde yan itki ve iticilerle sağlanır.", category: "Manevra" },
  { id: 183, question: "Acil durdurma (crash stop) manevrası neden son çare olarak kullanılır?", options: ["Zaman aldığı için", "Yakıt tükettiği için", "Durma mesafesinin uzun olması ve gemi kontrolünün geçici olarak kaybedilmesi nedeniyle", "Gürültü nedeniyle"], correctAnswer: 2, explanation: "Büyük gemilerde durma mesafesi gemi boyunun birkaç katıdır ve manevra sırasında baş savrulur; genellikle rota değişikliği daha etkilidir.", category: "Manevra" },
  { id: 184, question: "Gemi boyu 200 m ve durma mesafesi gemi boyunun 8 katı ise durma mesafesi kaç metredir?", options: ["2,000 m", "800 m", "1,200 m", "1,600 m"], correctAnswer: 3, explanation: "Durma mesafesi = 200 × 8 = 1,600 m; manevra karakteristikleri levhasında bu değerler yer alır.", category: "Manevra" },
  { id: 185, question: "Manevra karakteristikleri levhası (wheelhouse poster) köprüüstünde neden bulunur?", options: ["Dönüş dairesi, durma mesafesi ve manevra verilerinin anında görülebilmesi için", "Denetim için", "Kayıt için", "Süs için"], correctAnswer: 0, explanation: "SOLAS V/29 gereği levha görülebilir yerde asılır; kılavuz kartı ile birlikte hızlı karar vermeyi destekler.", category: "Manevra" },
  { id: 186, question: "Kılavuz kartı (pilot card) neyi içerir?", options: ["Mürettebat listesini", "Sefer planını", "Yük planını", "Geminin boyutları, draftı, makine ve dümen özellikleri ile manevra bilgilerini"], correctAnswer: 3, explanation: "Kılavuz gemiye çıktığında kartla birlikte bilgilendirilir; ayrıca yapılacak manevra ve beklentiler üzerinde karşılıklı anlaşılır.", category: "Vardiya" },
  { id: 187, question: "Kılavuz gemiye çıktığında kaptanın sorumluluğu ne olur?", options: ["Vardiyadan ayrılır", "Tamamen kılavuza geçer", "Kaptanın gemi ve emniyet sorumluluğu devam eder", "Yalnızca yükle ilgilenir"], correctAnswer: 2, explanation: "Kılavuz danışman olarak görev yapar; kaptan gerekli gördüğünde müdahale eder ve kılavuzun tavsiyesini reddedebilir.", category: "Vardiya" },
  { id: 188, question: "Köprüüstü ekip yönetiminde 'situational awareness' kaybının en yaygın belirtisi nedir?", options: ["Belirsizliklerin ve alarmların göz ardı edilmesi, plandan sapmanın fark edilmemesi", "Fazla soru sormak", "Sık konum almak", "Yüksek sesle konuşmak"], correctAnswer: 0, explanation: "Alarmların susturulması, teyit edilmemiş varsayımlar ve 'her şey yolunda' varsayımı klasik uyarı işaretleridir; çapraz kontrol şarttır.", category: "Vardiya" },
  { id: 189, question: "Köprüüstünde 'çapraz kontrol' (cross-checking) neyi ifade eder?", options: ["Vardiya değişimini", "Alarm testini", "İki kişinin aynı ekranı izlemesini", "Konumun birbirinden bağımsız en az iki yöntemle doğrulanmasını"], correctAnswer: 3, explanation: "GNSS konumu radar mesafesi, görsel kerteriz veya derinlikle karşılaştırılır; tek kaynağa bağımlılık en sık karaya oturma nedenlerindendir.", category: "Vardiya" },
  { id: 190, question: "Vardiya sırasında ECDIS alarmlarının kapatılması neden tehlikelidir?", options: ["Kayıt tutulmadığı için", "Ekranı bozduğu için", "Pil tükettiği için", "Emniyet ağının devre dışı kalması ve tehlikelerin fark edilmemesi nedeniyle"], correctAnswer: 3, explanation: "Sık alarm sorunu doğru parametre ayarıyla çözülür; alarmların topluca kapatılması birçok kazanın ortak nedenidir.", category: "Vardiya" },
  { id: 191, question: "Gemide 'safe access' (güvenli erişim) neyi gerektirir?", options: ["Yalnızca levha", "Yalnızca merdiven", "Aydınlatılmış, korkuluklu, engelsiz ve kaymaz geçiş yolları", "Yalnızca halat"], correctAnswer: 2, explanation: "Rıhtım-gemi arası ve güverte içi geçişler güvenli olmalı; iskele altına emniyet ağı ve can simidi konur.", category: "İş Emniyeti" },
  { id: 192, question: "Gemi iskelesi (gangway) altında emniyet ağı neden bulunur?", options: ["Görüntü için", "Rüzgâr için", "Yük düşmesin diye", "Kişi veya eşya düşmesi hâlinde denize düşmeyi engellemek için"], correctAnswer: 3, explanation: "Ağ, iskeleden düşme hâlinde su ile temas riskini azaltır; ayrıca ışıklı can simidi hazır bulundurulur.", category: "İş Emniyeti" },
  { id: 193, question: "Yüksekte çalışma öncesi hava koşullarının değerlendirilmesi neden zorunludur?", options: ["Konfor için", "Rüzgâr ve gemi hareketinin düşme riskini belirgin biçimde artırması nedeniyle", "Görüş için", "Boya kuruması için"], correctAnswer: 1, explanation: "Yalpa ve baş-kıç vurma dengeyi bozar; belirlenen eşiklerin üzerinde çalışma ertelenir.", category: "İş Emniyeti" },
  { id: 194, question: "Kaynak işi sonrası yangın gözcüsü ne kadar süre görevde kalmalıdır?", options: ["İş bittikten sonra da belirli bir süre (tipik olarak en az 30 dakika) bölgeyi izlemelidir", "Yalnızca iş sırasında", "1 hafta", "Derhal ayrılabilir"], correctAnswer: 0, explanation: "Gizli kalmış kıvılcım veya sıcak nokta gecikmeli yangına yol açabilir; izleme süresi izin belgesinde tanımlanır.", category: "İş Emniyeti" },
  { id: 195, question: "Gemi güvertesinde elektrikli el aleti kullanırken temel önlem nedir?", options: ["Aleti hızlı kullanmak", "Eldiven takmamak", "Kabloyu uzatmak", "Kablo bütünlüğünü kontrol etmek, uygun gerilim ve topraklama/izolasyon kullanmak"], correctAnswer: 3, explanation: "Islak güvertede elektrik çarpması riski yüksektir; düşük gerilimli veya çift izolasyonlu aletler ile kaçak akım koruması tercih edilir.", category: "İş Emniyeti" },
  { id: 196, question: "Kapalı mahalde iş sırasında gaz ölçümünün tekrarlanma nedeni nedir?", options: ["Aydınlatma için", "Cihaz kalibrasyonu için", "Çalışma sırasında atmosferin değişebilmesi nedeniyle", "Kayıt için"], correctAnswer: 2, explanation: "Yeni açılan yüzeyler, kaynak dumanı veya kalıntılar ortamı hızla değiştirebilir; ölçüm sürekli veya düzenli aralıklarla yapılır.", category: "İş Emniyeti" },
  { id: 197, question: "Ağır havada denize açılma kararı verilirken hangi bilgi belirleyicidir?", options: ["Yük fiyatı", "Vardiya planı", "Liman ücretleri", "Güncel hava/deniz tahmini ile geminin yükleme ve stabilite durumu"], correctAnswer: 3, explanation: "Kaptan denize elverişlilikten sorumludur; hava tahmini, GM, yükleme durumu ve bağlamalar birlikte değerlendirilir.", category: "Ağır Hava" },
  { id: 198, question: "Parametrik yalpa tespit edildiğinde ilk uygulanacak önlem nedir?", options: ["Rota ve/veya hızı değiştirerek karşılaşma periyodunu rezonanstan çıkarmak", "Balast almak", "Demirlemek", "Hızı artırmak"], correctAnswer: 0, explanation: "Rezonans karşılaşma periyoduna bağlıdır; küçük bir rota veya hız değişikliği yalpayı hızla söndürebilir.", category: "Ağır Hava" },
  { id: 199, question: "Ağır havada serbest yüzeylerin azaltılması neden önemlidir?", options: ["Trim için", "Hız için", "Yakıt tasarrufu için", "Etkin GM'yi koruyup ani meyil riskini azaltmak için"], correctAnswer: 3, explanation: "Slack tanklar FSM üretir; hava kötüleşmeden tanklar mümkün olduğunca tam doldurulur veya boşaltılır.", category: "Ağır Hava" },
  { id: 200, question: "Güverte yükü buzlanmaya başladığında ilk yapılması gereken nedir?", options: ["Balast boşaltmak", "Yükü denize atmak", "Buz birikimini temizlemek ve mümkünse rota/hız değiştirerek serpintiyi azaltmak", "Hız artırmak"], correctAnswer: 2, explanation: "Buz üstte biriktiğinden KG hızla yükselir; temizlik güvenli olduğu ölçüde sürdürülür ve gerekirse sığınma limanı değerlendirilir.", category: "Ağır Hava" },
  { id: 201, question: "Yangın alarmında güverte personelinin ilk görevi nedir?", options: ["Yangına müdahale etmek", "Muster listesindeki istasyona giderek yoklamaya katılmak ve göreve hazır olmak", "Kamaraya gitmek", "Beklemek"], correctAnswer: 1, explanation: "Yoklama, kayıp personel olup olmadığını hızla belirler; müdahale ekipleri organize biçimde yönlendirilir.", category: "Acil Durum" },
  { id: 202, question: "Acil durumda yoklamanın (muster/head count) kritikliği nereden gelir?", options: ["Vardiya düzeni", "Denetim", "Kayıt tutmak", "Kayıp kişinin varlığını erken belirleyip arama kararını hızlandırması"], correctAnswer: 3, explanation: "Eksik kişi tespit edildiğinde arama ekibi derhal görevlendirilir; geç fark edilen kayıp müdahale şansını azaltır.", category: "Acil Durum" },
  { id: 203, question: "Gemi yangınında ilk müdahale ekibinin köprüüstüne bildirmesi gereken temel bilgi nedir?", options: ["Yangının yeri, türü, büyüklüğü ve yayılma yönü", "Personel isimleri", "Yakıt miktarı", "Yangının rengi"], correctAnswer: 0, explanation: "Bu bilgi söndürme yöntemini, sınır soğutma ihtiyacını ve sabit sistem kararını belirler.", category: "Acil Durum" },
  { id: 204, question: "Denizde kirlilik olayı meydana geldiğinde SOPEP planı neyi tanımlar?", options: ["Yalnızca cezayı", "Yalnızca temizlik yöntemini", "Raporlama zinciri, ilk müdahale adımları ve sorumlulukları", "Yalnızca sigortayı"], correctAnswer: 2, explanation: "SOPEP; kime, ne zaman ve nasıl bildirileceğini, sızıntının sınırlandırılmasını ve kullanılacak malzemeyi tanımlar.", category: "Acil Durum" },
  { id: 205, question: "Petrol sızıntısında güvertede ilk müdahale nedir?", options: ["Suyla yıkamak", "Beklemek", "Denize deterjan dökmek", "Sızıntı kaynağını durdurup güverte scupper'larını kapatmak ve emici malzeme kullanmak"], correctAnswer: 3, explanation: "Öncelik denize ulaşmasını engellemektir; scupper tapaları kapatılır, SOPEP dolabındaki emiciler kullanılır ve derhal bildirim yapılır.", category: "Acil Durum" },
  { id: 206, question: "Can salı şişirildikten sonra içeri girildiğinde ilk kontrol nedir?", options: ["Yiyecek sayımı", "Salın hasarsız olduğunun, şişme basıncının ve girişin kapatıldığının kontrolü", "Kürek sayımı", "Su sayımı"], correctAnswer: 1, explanation: "Kaçak veya hasar erken tespit edilmeli; ardından deniz demiri atılır, su boşaltılır ve hipotermiye karşı önlem alınır.", category: "Can Kurtarma" },
  { id: 207, question: "Can salında kurtarma beklerken salların bir arada tutulması neden önerilir?", options: ["Ağırlık için", "Hız için", "Sohbet için", "Daha büyük ve kolay görülebilir bir hedef oluşturması ve kaynak paylaşımı için"], correctAnswer: 3, explanation: "Bağlanan sallar radar ve görsel aramada daha kolay bulunur; ayrıca moral ve malzeme paylaşımı sağlanır.", category: "Can Kurtarma" },
  { id: 208, question: "Denizde hayatta kalmada su tüketiminin ilk 24 saatte kısıtlanması neden önerilir?", options: ["Tat için", "Su bozulmasın diye", "Vücudun mevcut sıvı dengesini koruması ve stoğun uzun süreye yayılması için", "Ağırlık için"], correctAnswer: 2, explanation: "İlk gün genellikle su verilmez veya çok az verilir; sonraki günlerde günlük yaklaşık yarım litre bölünerek tüketilir.", category: "Can Kurtarma" },
  { id: 209, question: "Kurtarma helikopteri gelirken can salında yapılması gereken nedir?", options: ["Sinyal fişeğini helikoptere doğrultmak", "Salı terk etmek", "Ayağa kalkmak", "Talimatları beklemek, gevşek eşyaları emniyete almak ve hoist teline elle dokunmadan önce topraklanmasını beklemek"], correctAnswer: 3, explanation: "Statik elektrik yüklü hoist teli suya veya salın metal kısmına değdirilerek boşaltılmalıdır; ayrıca rotor akımı gevşek eşyayı savurur.", category: "Can Kurtarma" },
  { id: 210, question: "Gemi bakımında planlı boyama programının amacı nedir?", options: ["Korozyonun ilerlemeden durdurulması ve yapısal ömrün korunması", "Ağırlık artırmak", "Denetim geçmek", "Görsellik"], correctAnswer: 0, explanation: "Erken müdahale edilen pas noktası ucuz ve kolaydır; ihmal edildiğinde sac incelmesi ve yapısal onarım gerekir.", category: "Bakım" },
  { id: 211, question: "Balast tanklarının düzenli muayenesi neden kritiktir?", options: ["Hacim ölçümü için", "Temizlik için", "Su kalitesi için", "Kaplama bozulması ve yapısal korozyonun erken tespiti için"], correctAnswer: 3, explanation: "Balast tankları en agresif korozyon ortamıdır; kaplama ve anot durumu planlı olarak muayene edilir ve kayıt tutulur.", category: "Bakım" },
  { id: 212, question: "Güverte donanımında paslanmaya karşı en etkili günlük önlem nedir?", options: ["Örtü kullanmak", "Yağlı bez kullanmak", "Tuzlu su kalıntısını tatlı su ile yıkayıp kurutmak", "Boya kalınlığını artırmak"], correctAnswer: 2, explanation: "Tuz nem çekerek korozyonu hızlandırır; düzenli tatlı su yıkaması, özellikle vinç ve makara bölgelerinde çok etkilidir.", category: "Bakım" },
  { id: 213, question: "Ambar kapağı contası değişiminde en kritik nokta nedir?", options: ["Doğru profil ve doğru sıkışma payının sağlanması", "Conta uzunluğu", "Yapıştırıcı markası", "Conta rengi"], correctAnswer: 0, explanation: "Yanlış profil veya aşırı/eksik sıkışma sızdırmazlığı bozar; kanal ve baskı çubuğu da birlikte kontrol edilir.", category: "Bakım" },
  { id: 214, question: "Sintine ve güverte drenaj hatlarının açık tutulması neden önemlidir?", options: ["Boya için", "Ağırlık için", "Koku için", "Su birikmesini önleyerek serbest yüzey ve kayma riskini azaltmak için"], correctAnswer: 3, explanation: "Tıkalı drenaj güvertede su biriktirir; hem stabiliteyi hem yürüme emniyetini olumsuz etkiler.", category: "Bakım" },
  { id: 215, question: "Gemide kullanılan kaldırma sapanlarının (sling) muayenesinde neye bakılır?", options: ["Uzunluğuna", "Ağırlığına", "Rengine", "Kesik, aşınma, kimyasal hasar ve etiket/SWL okunabilirliğine"], correctAnswer: 3, explanation: "Etiketi okunmayan veya hasarlı sapan derhal hizmet dışı bırakılır; kayıtlar kaldırma donanımı defterinde tutulur.", category: "Bakım" },
  { id: 216, question: "Demirleme öncesi dip yapısının bilinmesi neden gereklidir?", options: ["Akıntı için", "Zincir uzunluğu için", "Tutma gücünün dip cinsine göre büyük ölçüde değişmesi nedeniyle", "Derinlik için"], correctAnswer: 2, explanation: "Çamur ve kum iyi tutar; kaya, mercan ve çakıl zayıf tutar. Harita dip işaretleri demirleme yeri seçiminde belirleyicidir.", category: "Demirleme" },
  { id: 217, question: "Demirleme sırasında geminin yolunun kesilmiş olması neden şarttır?", options: ["Gürültü için", "Konum için", "Yakıt tasarrufu için", "Zincirin ve ırgatın aşırı zorlanmasını, zincirin kopmasını önlemek için"], correctAnswer: 3, explanation: "Hafif tornistanla yol kesilir ve zincir kontrollü biçimde verilir; ileri yolda demir bırakmak donanımı tahrip eder.", category: "Demirleme" },
  { id: 218, question: "Fırtınada demirde kalan gemide alınacak önlem nedir?", options: ["Zinciri kısaltmak", "Kalomayı artırmak, makineyi hazır tutmak ve gerekirse demir alıp açığa çıkmak", "Işıkları söndürmek", "Beklemek"], correctAnswer: 1, explanation: "Tutuş bozulursa gemi hızla karaya sürüklenir; makine hazır tutulur ve emniyet payı kalmadan önce açığa çıkma kararı verilir.", category: "Demirleme" },
  { id: 219, question: "Palamar operasyonunda halat sayısının plana göre belirlenmesi neden gerekir?", options: ["Rüzgâr, akıntı ve gelgit kuvvetlerini dengeli karşılamak için", "Zaman için", "Maliyet için", "Estetik için"], correctAnswer: 0, explanation: "Halatlar simetrik ve dengeli düzenlenir; aksi hâlde tek bir halat aşırı yüklenerek kopar ve zincirleme kopma başlar.", category: "Palamar" },
  { id: 220, question: "Gelgit farkı büyük limanlarda palamar halatlarının izlenmesi neden gerekir?", options: ["Boya için", "Yük için", "Görüntü için", "Su seviyesi değiştikçe halatların aşırı gerilmesi veya boşalması nedeniyle"], correctAnswer: 3, explanation: "Gelgitle birlikte halatlar düzenli olarak ayarlanır; ihmal edilirse halat kopar veya gemi rıhtımdan açılır.", category: "Palamar" },
  { id: 221, question: "Fare siperliği (rat guard) ne işe yarar?", options: ["Işık vermek", "Halatı korumak", "Kemirgenlerin halat üzerinden gemiye geçmesini engellemek", "Suyu kesmek"], correctAnswer: 2, explanation: "Sağlık ve karantina gereklerinin parçasıdır; limanlarda halatlara takılması genellikle zorunludur.", category: "Palamar" },
  { id: 222, question: "Halatların depolanmasında dikkat edilmesi gereken nedir?", options: ["Islak istiflemek", "Sıkı sarmak", "Güneş altında bırakmak", "Kuru, havadar, güneş ve kimyasaldan korunmuş bir yerde saklamak"], correctAnswer: 3, explanation: "UV ışını ve kimyasallar sentetik lifleri zayıflatır; ıslak istifleme ise küflenme ve dayanım kaybı yapar.", category: "Bakım" },
  { id: 223, question: "COLREG'e göre 'yol alan' (underway) gemi tanımı nedir?", options: ["Demirli, karaya bağlı veya oturmuş olmayan gemi", "Yalnızca makinesi çalışan gemi", "Manevra yapan gemi", "Yol yapan gemi"], correctAnswer: 0, explanation: "Underway ile 'making way' (su üzerinde yol yapmak) farklıdır; makine durmuş olsa da gemi underway olabilir.", category: "COLREG" },
  { id: 224, question: "COLREG'e göre 'kısıtlı görüş' hangi durumları kapsar?", options: ["Yalnızca geceyi", "Yalnızca yağmuru", "Yalnızca sisi", "Sis, pus, kar, sağanak yağmur, kum fırtınası ve benzeri her türlü koşulu"], correctAnswer: 3, explanation: "Kural 3(l): görüşü kısıtlayan her koşul kapsamdadır; Kural 19 bu koşullarda uygulanır ve emniyetli hız zorunludur.", category: "COLREG" },
  { id: 225, question: "COLREG'de 'emniyetli hız' nasıl belirlenir?", options: ["Liman kurallarına göre", "Sabit bir değer olarak", "Koşullara göre çarpışmayı önleyecek ve uygun mesafede durdurulabilecek hız olarak", "Servis hızının yarısı olarak"], correctAnswer: 2, explanation: "Kural 6 emniyetli hızı sabit bir sayıya bağlamaz; görüş, trafik, manevra kabiliyeti, derinlik ve radar durumu birlikte değerlendirilir.", category: "COLREG" },
  { id: 226, question: "Geçme (overtaking) durumunda geçen geminin yükümlülüğü ne zaman sona erer?", options: ["Yan yana geldiğinde", "Geçilen gemiyi tamamen geçip emniyetle uzaklaştığında", "Kerteriz değiştiğinde", "Telsizle anlaştığında"], correctAnswer: 1, explanation: "Kural 13: sonradan değişen kerteriz geçen gemiyi yükümlülükten kurtarmaz; yükümlülük tamamen geçilip ayrılana kadar sürer.", category: "COLREG" },
  { id: 227, question: "Trafik ayrım düzenine (TSS) girerken temel kural nedir?", options: ["Şeride dik girilmelidir", "Girmeden önce demirlenir", "Her açıdan girilebilir", "Şerit yönünde ve mümkün olduğunca küçük açıyla girilmelidir"], correctAnswer: 3, explanation: "Kural 10: giriş/çıkış uçlardan yapılır; şeridi kesmek zorunluysa geçiş rota doğrultusuna mümkün olduğunca dik açıyla yapılır.", category: "COLREG" },
  { id: 228, question: "TSS'de trafik şeridini kesmek zorunlu ise nasıl geçilmelidir?", options: ["Genel trafik yönüne mümkün olduğunca dik açıyla", "45 derece açıyla", "Rastgele", "Şeride paralel"], correctAnswer: 0, explanation: "Dik geçiş, şerit içinde geçirilen süreyi en aza indirir ve niyeti diğer gemilere açıkça gösterir.", category: "COLREG" },
  { id: 229, question: "Demirde beklerken makine hazırlık süresinin bilinmesi neden önemlidir?", options: ["Kayıt için", "Yakıt için", "Acil durumda demir alma ve manevra kararının zamanında verilebilmesi için", "Bakım için"], correctAnswer: 2, explanation: "Hava bozduğunda makinenin hazır hâle gelme süresi kritik zaman payını belirler; kaptan bu süreyi hesaba katarak karar verir.", category: "Demirleme" },
  { id: 230, question: "Gemide 'permit to work' sisteminin gemicilik işlerindeki rolü nedir?", options: ["Personel değerlendirmek", "Maliyet takibi", "Kayıt tutmak", "Yüksek riskli işlerin planlanıp kontrollerin doğrulanmasını sağlamak"], correctAnswer: 3, explanation: "Yüksekte, borda dışında, kapalı mahalde ve sıcak işlerde izin zorunludur; izin kontrol listeleriyle birlikte imzalanır.", category: "İş Emniyeti" },
  { id: 231, question: "Boyalı veya ıslak güvertede yürürken temel önlem nedir?", options: ["Hızlı yürümek", "Uyarı levhası, alternatif geçiş ve kaymaz ayakkabı kullanmak", "Koşmak", "Eldiven takmak"], correctAnswer: 1, explanation: "Islak/boyalı alanlar işaretlenip mümkünse kapatılır; alternatif güvenli geçiş gösterilir.", category: "İş Emniyeti" },
  { id: 232, question: "Gemide gece güverte çalışmalarında ek önlem nedir?", options: ["Yalnız çalışmak", "Hızlı bitirmek", "Işıkları kısmak", "Yeterli aydınlatma, ek gözcü ve haberleşme sağlanması"], correctAnswer: 3, explanation: "Görüş kısıtlı olduğu için risk artar; portatif aydınlatma, telsiz teması ve düzenli kontrol zorunludur.", category: "İş Emniyeti" },
  { id: 233, question: "Vinç halatının makaradan (sheave) çıkması hangi riski doğurur?", options: ["Boya hasarı", "Yalnızca gecikme", "Halatın hasar görmesi ve yükün ani düşmesi", "Gürültü"], correctAnswer: 2, explanation: "Halatın yuvasından çıkması hem halatı keser hem de kontrolsüz düşmeye yol açar; operasyon derhal durdurulur.", category: "İş Emniyeti" },
  { id: 234, question: "Gemi ambarına inerken merdiven kullanımında temel kural nedir?", options: ["Hızlı inmek", "Tek elle tutunmak", "Elde malzeme taşıyarak inmek", "Üç nokta temas kuralına uymak ve malzemeyi ayrı yöntemle indirmek"], correctAnswer: 3, explanation: "İki el bir ayak veya iki ayak bir el daima temasta olmalıdır; malzeme halat veya çanta ile ayrıca indirilir.", category: "İş Emniyeti" },
  { id: 235, question: "Denizde adam düştü tatbikatında kurtarma botu ekibinin hazırlığı neyi kapsar?", options: ["Can yeleği, immersiyon/koruyucu giysi, telsiz, ilk yardım ve bot donanımı kontrolü", "Yalnızca telsiz", "Yalnızca kürek", "Yalnızca can yeleği"], correctAnswer: 0, explanation: "Ekip önceden belirlenir ve donanım hazır tutulur; tatbikat gerçek koşullara mümkün olduğunca yakın yapılır.", category: "Can Kurtarma" },
  { id: 236, question: "Kurtarma botu (rescue boat) ile can filikası arasındaki temel fark nedir?", options: ["Can filikası daha hızlıdır", "Fark yoktur", "Kurtarma botu daha büyüktür", "Kurtarma botu hızlı manevra ve suda kişi almak için tasarlanmıştır"], correctAnswer: 3, explanation: "Kurtarma botu manevra kabiliyeti yüksek, yandan kişi alınabilen ve hızla indirilebilen bir teknedir; can filikası ise toplu tahliye içindir.", category: "Can Kurtarma" },
  { id: 237, question: "Denizden alınan kazazedeye ilk yapılacak işlem nedir?", options: ["Yürütmek", "Sıcak duş aldırmak", "Islak giysileri çıkarıp kuru ve yalıtımlı biçimde sarmak, yatay tutmak", "Alkol vermek"], correctAnswer: 2, explanation: "Hipotermide ani ısıtma ve hareket tehlikelidir; kazazede yatay tutulur, pasif olarak ısıtılır ve tıbbi tavsiye alınır.", category: "Can Kurtarma" },
  { id: 238, question: "Gemi terk edilirken mümkünse ne yapılmalıdır?", options: ["Kuru ayakla doğrudan can filikası veya salına geçmek", "Yüzerek uzaklaşmak", "Beklemek", "Suya atlamak"], correctAnswer: 0, explanation: "Suya girmek hipotermi ve yaralanma riskini büyütür; mümkün olan her durumda kuru geçiş tercih edilir.", category: "Can Kurtarma" },
  { id: 239, question: "Gemi terk sonrası saldan ayrılmamak neden önerilir?", options: ["Yiyecek orada olduğu için", "Ağırlık için", "Kural olduğu için", "Salın aranan hedef olması ve yüzmenin ısı kaybını hızlandırması nedeniyle"], correctAnswer: 3, explanation: "Arama ekipleri sal ve gemi enkazı çevresini tarar; sudan uzaklaşan kişinin bulunma şansı hızla azalır.", category: "Can Kurtarma" },
  { id: 240, question: "Gemide su geçirmez kapıların seyir sırasında kapalı tutulması neden gerekir?", options: ["Gürültü için", "Havalandırma için", "Isı kaybını önlemek için", "Su alma hâlinde su yayılımını sınırlayarak bölmelendirmeyi işlevsel kılmak için"], correctAnswer: 3, explanation: "Bölmelendirme yalnızca kapılar kapalıyken hasarlı stabilite hesabındaki korumayı sağlar; açık bırakılan kapı bu korumayı ortadan kaldırır.", category: "Acil Durum" },
  { id: 241, question: "Hasar kontrol planı (damage control plan) neyi gösterir?", options: ["Personel listesini", "Yük yerleşimini", "Su geçirmez bölmeleri, kapıları, valfleri ve pompalama düzenini", "Sefer rotasını"], correctAnswer: 2, explanation: "Plan, su alma hâlinde hangi kapı ve valflerin kapatılacağını ve hangi pompaların kullanılacağını gösterir; kolay erişilir yerde bulundurulur.", category: "Acil Durum" },
  { id: 242, question: "Su alan bir bölmede pompalamanın etkisiz kalması neyi gösterir?", options: ["Bölmenin dolduğunu", "Trim değiştiğini", "Pompa arızasını mutlaka", "Su giriş debisinin pompa kapasitesini aştığını"], correctAnswer: 3, explanation: "Bu durumda öncelik yırtığı sınırlandırmak ve komşu bölmeleri korumaktır; ayrıca stabilite yeniden değerlendirilir ve yardım istenir.", category: "Acil Durum" },
  { id: 243, question: "Acil durumda VHF kanal 16'nın dinlenmesi neden zorunludur?", options: ["Hava raporu için", "Tehlike ve acil durum çağrılarının uluslararası dinleme kanalı olması nedeniyle", "Liman için", "Acente için"], correctAnswer: 1, explanation: "Kanal 16 tehlike, acil ve çağrı kanalıdır; sürekli dinlenmesi hem kendi çağrımızın hem de başkasının duyulmasını sağlar.", category: "Acil Durum" },
  { id: 244, question: "Gemide acil durum çizelgesinde (contingency plan) 'senaryo tabanlı' yaklaşım ne sağlar?", options: ["Ekibin olası olaylara önceden hazırlanmasını ve rollerin netleşmesini", "Maliyet düşürme", "Denetim geçme", "Kayıt kolaylığı"], correctAnswer: 0, explanation: "Yangın, su alma, MOB, kirlilik gibi senaryolar ayrı ayrı planlanır ve tatbikatlarla denenerek eksikler giderilir.", category: "SMS" },
  { id: 245, question: "Gemide bakım kayıtlarının doğru tutulması neden önemlidir?", options: ["Maliyet için", "Personel için", "Denetim için yeterlidir", "Ekipman geçmişinin izlenip arıza eğilimlerinin görülmesini sağladığı için"], correctAnswer: 3, explanation: "Kayıtlar tekrarlayan arızaları ortaya çıkarır ve kök neden analizine veri sağlar; ayrıca klas ve PSC denetimlerinde kanıttır.", category: "SMS" },
  { id: 246, question: "Gemide 'çalışma izni olmadan iş yapılmaz' kuralının temel gerekçesi nedir?", options: ["Personeli meşgul etmek", "Bürokrasi", "Kontrollerin ve hazırlıkların yapıldığının bağımsız olarak doğrulanması", "Kayıt tutmak"], correctAnswer: 2, explanation: "İzin, işi onaylayan kişinin riskleri ve alınan önlemleri bizzat doğrulamasını gerektirir; bu bağımsız kontrol katmanı kazaları önler.", category: "SMS" },
  { id: 247, question: "Gemide vardiya tutan personelin sayısı belirlenirken neye bakılır?", options: ["Yalnızca yük türüne", "Yalnızca sefer süresine", "Yalnızca gemi boyuna", "Görüş, trafik, seyir bölgesi, hava ve gemi donanımına"], correctAnswer: 3, explanation: "STCW: vardiya kompozisyonu koşullara göre belirlenir; şüphe hâlinde takviye yapılır ve tek başına vardiya sürdürülmez.", category: "Vardiya" },
  { id: 248, question: "Gece vardiyasında köprüüstü aydınlatmasının kısılması neden gereklidir?", options: ["Gözün karanlığa uyumunun korunması ve dışarının görülebilmesi için", "Ekran ömrü için", "Uyku için", "Enerji tasarrufu için"], correctAnswer: 0, explanation: "Karanlığa uyum yaklaşık 20–30 dakika sürer ve parlak ışıkla anında bozulur; ekranlar da gece moduna alınır.", category: "Vardiya" },
  { id: 249, question: "Radar ve ECDIS ekran parlaklığının gece ayarlanmasının amacı nedir?", options: ["Enerji tasarrufu", "Kayıt kalitesi", "Cihazı korumak", "Görsel gözlemi bozmadan bilgiyi okuyabilmek"], correctAnswer: 3, explanation: "Aşırı parlak ekran dışarıyı görünmez kılar; gece paleti ve kısılmış parlaklıkla hem ekran hem dış gözlem sürdürülür.", category: "Vardiya" },
  { id: 250, question: "Bir geminin manevra kabiliyetini en çok etkileyen yükleme parametresi nedir?", options: ["Ambar sayısı", "Yük cinsi", "Draft ve trim durumu", "Yük değeri"], correctAnswer: 2, explanation: "Draft omurga altı boşluğu ve squat'ı, trim ise dümen/pervane daldırmasını ve dönme noktasını etkiler; balast seferinde manevra belirgin farklıdır.", category: "Manevra" },
  { id: 251, question: "Balast seferinde (light condition) manevrayı zorlaştıran temel etken nedir?", options: ["Düşük hız", "Rüzgâra maruz kalan büyük su üstü alan ve azalan pervane/dümen daldırması", "Yüksek yakıt tüketimi", "Ağır gövde"], correctAnswer: 1, explanation: "Su üstü alan büyüdüğünden gemi rüzgârdan çok etkilenir; ayrıca pervane ve dümen yeterince batmadığı için itki ve dümen etkinliği düşer.", category: "Manevra" },
  { id: 252, question: "Yanaşma manevrasında römorkör sayısı neye göre belirlenir?", options: ["Yük cinsine", "Sefer süresine", "Liman ücretine", "Gemi büyüklüğü, hava/akıntı koşulları ve itici donanımına"], correctAnswer: 3, explanation: "Kılavuz ve kaptan birlikte değerlendirir; yetersiz römorkör desteği kontrolü kaybettirebilir, bu yüzden şüphe hâlinde takviye istenir.", category: "Manevra" },
  { id: 253, question: "Manevra öncesi köprüüstü ekibi brifinginde ne paylaşılır?", options: ["Plan, rol dağılımı, kritik noktalar ve beklenmedik durumda uygulanacak seçenek", "Yalnızca hava durumu", "Yalnızca yük bilgisi", "Yalnızca varış saati"], correctAnswer: 0, explanation: "Ortak zihinsel model oluşturulur; herkes ne bekleyeceğini bildiğinden sapma erken fark edilir ve müdahale hızlanır.", category: "Manevra" },
  { id: 254, question: "Manevra sırasında 'abort point' (vazgeçme noktası) neyi ifade eder?", options: ["Rıhtım başlangıcını", "Demirleme noktasını", "Manevradan güvenle vazgeçilebilecek son konumu", "Kılavuz alma noktasını"], correctAnswer: 2, explanation: "Bu noktadan sonra geri dönüş güvenli değildir; plan önceden bu noktayı ve vazgeçme kriterlerini tanımlamalıdır.", category: "Manevra" },
  { id: 255, question: "Gemicilikte 'iyi denizcilik uygulaması' (good seamanship) ne anlama gelir?", options: ["Hızlı çalışmak", "Ekonomik davranmak", "Kuralları harfiyen uygulamak", "Kuralların ötesinde, koşulların gerektirdiği makul ve öngörülü davranışı sergilemek"], correctAnswer: 3, explanation: "COLREG Kural 2 bu ilkeyi açıkça anar: kuralların eksik kaldığı yerde deneyim, öngörü ve sağduyu belirleyicidir.", category: "COLREG" },
];
